const grid=document.querySelector('#service-grid');
services.forEach((s,i)=>{const el=document.createElement('article');el.className='service';el.dataset.category=s[1];el.innerHTML=`<div class="service-top"><span class="service-icon" aria-hidden="true">${s[2]}</span><span class="service-num">${String(i+1).padStart(2,'0')}</span></div><h3>${s[0]}</h3><p>${s[3]}</p><button type="button" aria-label="Explore ${s[0]}">Explore service <span>↗</span></button>`;el.querySelector('button').addEventListener('click',()=>openService(i));grid.append(el);const option=document.createElement('option');option.textContent=s[0];document.querySelector('select[name=service]').append(option)});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});document.querySelectorAll('.service').forEach(c=>c.hidden=button.dataset.filter!=='all'&&c.dataset.category!==button.dataset.filter)}));
const serviceDialog=document.querySelector('#service-dialog');function openService(i){const s=services[i];serviceDialog.querySelector('h2').textContent=s[0];serviceDialog.querySelector('.dialog-description').textContent=s[3];const ul=serviceDialog.querySelector('ul');ul.replaceChildren(...s[4].map(t=>{const li=document.createElement('li');li.textContent=t;return li}));serviceDialog.querySelector('.service-cta').onclick=()=>{document.querySelector('select[name=service]').value=s[0];serviceDialog.close()};serviceDialog.showModal()}
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
document.querySelector('#privacy-open').onclick=()=>document.querySelector('#privacy-dialog').showModal();
const menu=document.querySelector('.menu');menu.onclick=()=>{const open=document.querySelector('#nav').classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation')};document.querySelectorAll('#nav a').forEach(a=>a.onclick=()=>{document.querySelector('#nav').classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation')});
document.querySelector('#inquiry').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const message=`Hello Zaki Tech Support,\n\nName: ${f.get('name')}\nCompany: ${f.get('company')||'Not provided'}\nService: ${f.get('service')}\n\nRequirement:\n${f.get('message')}`;window.open('https://wa.me/923180845793?text='+encodeURIComponent(message),'_blank','noopener,noreferrer')});document.querySelector('#year').textContent=new Date().getFullYear();

const themeToggle=document.querySelector('#theme-toggle');
function syncThemeControl(){const dark=document.documentElement.dataset.theme==='dark';themeToggle.setAttribute('aria-pressed',String(dark));themeToggle.setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode');themeToggle.querySelector('.theme-label').textContent=dark?'Dark':'Light';document.querySelector('meta[name="theme-color"]').content=dark?'#0c121c':'#f6f7fb';}
themeToggle.addEventListener('click',()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;document.documentElement.style.colorScheme=theme;try{localStorage.setItem('zaki-theme',theme)}catch{}syncThemeControl()});
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',e=>{let saved;try{saved=localStorage.getItem('zaki-theme')}catch{}if(!saved){document.documentElement.dataset.theme=e.matches?'dark':'light';document.documentElement.style.colorScheme=e.matches?'dark':'light';syncThemeControl()}});syncThemeControl();
